/**
 * Section Library - Left Sidebar
 * Purpose: Display categorized section templates for adding to canvas
 * Author: generated by Amazon Q
 * Created: 2024-01-15
 */

'use client';

import React, { useEffect, useState } from 'react';
import { Eye } from 'lucide-react';
import { Icon } from '@/components/admin/icons';
import type { SectionConfig } from '@/lib/page-builder/section-schemas';
import { SECTION_TEMPLATES, SECTION_CATEGORIES } from '@/lib/page-builder/section-registry';
import { SectionPreviewModal } from '@/components/section-preview/SectionPreviewModal';
import { getSectionPreviewData } from '@/lib/section-preview-data';
import { canEditCodeClient } from '@/lib/custom-html/client-role';
import { LibraryPicker } from './custom-html/LibraryPicker';

interface SectionLibraryProps {
  onAddSection: (templateType: string) => void;
  /** Layers tab (optional: without these the library behaves as before). */
  sections?: SectionConfig[];
  selectedSectionId?: string | null;
  onSelectSection?: (id: string) => void;
  onClose?: () => void;
  /** Opens the Custom HTML import wizard (shown only to users who may edit code). */
  onImportHtml?: () => void;
  /** Places a saved Custom HTML section. Omitted where custom HTML is not allowed (blog builder). */
  onInsertSection?: (section: SectionConfig) => void;
}

export function SectionLibrary({ onAddSection, sections, selectedSectionId, onSelectSection, onClose, onImportHtml, onInsertSection }: SectionLibraryProps) {
  const [canImport, setCanImport] = useState(false);
  useEffect(() => {
    setCanImport(canEditCodeClient());
  }, []);
  const [tab, setTab] = useState<'library' | 'layers'>('library');
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedCategories, setExpandedCategories] = useState<string[]>([
    SECTION_CATEGORIES.HEADERS,
    SECTION_CATEGORIES.CONTENT,
  ]);
  const [previewSection, setPreviewSection] = useState<{
    type: string;
    name: string;
    description: string;
  } | null>(null);

  const toggleCategory = (category: string) => {
    setExpandedCategories(prev =>
      prev.includes(category)
        ? prev.filter(c => c !== category)
        : [...prev, category]
    );
  };

  const filteredTemplates = SECTION_TEMPLATES.filter(template =>
    template.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    template.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const groupedTemplates = Object.values(SECTION_CATEGORIES).reduce((acc, category) => {
    acc[category] = filteredTemplates.filter(template => template.category === category);
    return acc;
  }, {} as Record<string, typeof SECTION_TEMPLATES>);

  return (
    <div className="w-[300px] max-w-full h-full bg-white border-r border-[#E4E7EC] flex flex-col dark:bg-gray-800 dark:border-gray-700">
      {/* Header */}
      <div className="p-3 border-b border-[#E4E7EC] space-y-3 dark:border-gray-700">
        <div className="flex items-center gap-2">
          <div className="flex flex-1 p-[3px] rounded-[10px] bg-[#F2F4F7] dark:bg-gray-900" role="tablist">
            {(['library', 'layers'] as const).map((t) => (
              <button
                key={t}
                role="tab"
                aria-selected={tab === t}
                onClick={() => setTab(t)}
                className={`flex-1 h-[30px] rounded-lg text-[13px] font-medium capitalize ${
                  tab === t ? 'bg-white text-[#101828] shadow-[0_1px_2px_rgba(16,24,40,.12)] dark:bg-gray-700 dark:text-white' : 'text-[#475467] dark:text-gray-300'
                }`}
              >
                {t}
                {t === 'layers' && sections ? ` (${sections.length})` : ''}
              </button>
            ))}
          </div>
          {onClose && (
            <button
              onClick={onClose}
              aria-label="Close library"
              className="xl:hidden w-8 h-8 grid place-items-center rounded-lg text-[#475467] hover:bg-[#F2F4F7] dark:text-gray-300 dark:hover:bg-gray-700"
            >
              <Icon name="close" />
            </button>
          )}
        </div>
        {tab === 'library' && (
          <input
            type="text"
            placeholder="Search sections..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full h-9 px-3 border border-[#D0D5DD] rounded-lg bg-white text-[#101828] text-sm focus:outline-none focus:ring-2 focus:ring-[#2563EB]/30 focus:border-[#2563EB] dark:bg-gray-700 dark:text-white dark:border-gray-600"
          />
        )}
      </div>

      {tab === 'layers' && (
        <div className="flex-1 overflow-y-auto p-2">
          {(sections ?? []).length === 0 && (
            <p className="text-sm text-[#667085] text-center py-8 dark:text-gray-400">No sections yet. Add one from the Library.</p>
          )}
          {(sections ?? []).map((sec, i) => {
            const tpl = SECTION_TEMPLATES.find((t) => t.type === sec.type);
            const active = sec.id === selectedSectionId;
            return (
              <button
                key={sec.id}
                onClick={() => onSelectSection?.(sec.id)}
                className={`w-full flex items-center gap-3 h-10 px-3 rounded-lg text-left text-sm ${
                  active ? 'bg-[#EEF4FF] text-[#1D4ED8] font-semibold dark:bg-blue-900/30 dark:text-blue-300' : 'text-[#101828] hover:bg-[#F2F4F7] dark:text-gray-200 dark:hover:bg-gray-700'
                }`}
              >
                <span className="w-5 text-xs text-[#667085] font-semibold dark:text-gray-400">{i + 1}</span>
                <span className="truncate">{tpl?.name ?? sec.type.replace(/Section$/, '').replace(/[-_]/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')}</span>
              </button>
            );
          })}
        </div>
      )}

      {/* Categories */}
      <div className={`flex-1 overflow-y-auto p-3 space-y-3 ${tab === 'library' ? '' : 'hidden'}`}>
        {onImportHtml && canImport && (
          <div data-testid="custom-html-block" className="rounded-lg border border-dashed border-blue-300 bg-blue-50/60 p-3 dark:border-blue-700 dark:bg-blue-900/10">
            <div className="mb-1 text-sm font-medium text-gray-900 dark:text-white">Custom HTML</div>
            <p className="mb-2 text-xs text-gray-600 dark:text-gray-400">
              Bring your own HTML, CSS and JS and turn it into an editable section.
            </p>
            <button
              type="button"
              onClick={onImportHtml}
              className="w-full rounded-md bg-blue-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-blue-700"
            >
              Import HTML…
            </button>
          </div>
        )}
        {Object.entries(groupedTemplates).map(([category, templates]) => {
          const isCustom = category === SECTION_CATEGORIES.CUSTOM;
          const showSaved = isCustom && !!onInsertSection;
          if (isCustom && !showSaved && templates.length === 0) return null;
          return (
          <div key={category} className="space-y-2">
            {/* Category Header */}
            <button
              onClick={() => toggleCategory(category)}
              className="flex items-center justify-between w-full text-left p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
            >
              <span className="font-medium text-gray-900 dark:text-white text-sm">
                {category}
              </span>
              <span className={`text-gray-500 transition-transform ${
                expandedCategories.includes(category) ? 'rotate-90' : ''
              }`}>
                ▶
              </span>
            </button>

            {/* Category Templates */}
            {expandedCategories.includes(category) && (
              <div className="space-y-2 ml-2">
                {templates.map((template) => (
                  <div key={template.id} className="relative group/card">
                    <button
                      onClick={() => onAddSection(template.type)}
                      className="w-full text-left p-3 rounded-lg border border-gray-200 dark:border-gray-600 hover:border-blue-300 dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-all"
                    >
                      <div className="flex items-start space-x-3">
                        {/* Icon */}
                        <div className="text-2xl group-hover/card:scale-110 transition-transform">
                          {template.icon}
                        </div>
                        
                        {/* Content */}
                        <div className="flex-1 min-w-0">
                          <h3 className="font-medium text-gray-900 dark:text-white text-sm mb-1">
                            {template.name}
                          </h3>
                          <p className="text-xs text-gray-600 dark:text-gray-400 line-clamp-2">
                            {template.description}
                          </p>
                        </div>
                      </div>
                    </button>
                    
                    {/* Preview Button */}
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setPreviewSection({
                          type: template.type,
                          name: template.name,
                          description: template.description,
                        });
                      }}
                      className="absolute top-2 right-2 p-1.5 bg-white dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md opacity-0 group-hover/card:opacity-100 hover:bg-blue-50 dark:hover:bg-blue-900/20 hover:border-blue-400 transition-all shadow-sm"
                      title="Preview Section"
                    >
                      <Eye className="w-3.5 h-3.5 text-gray-600 dark:text-gray-400" />
                    </button>
                  </div>
                ))}
                
                {showSaved && <LibraryPicker search={searchTerm} onInsert={onInsertSection!} />}

                {templates.length === 0 && !showSaved && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 italic ml-2">
                    No sections found
                  </p>
                )}
              </div>
            )}
          </div>
          );
        })}
      </div>

      {/* Footer */}
      <div className={`p-3 border-t border-[#E4E7EC] dark:border-gray-700 ${tab === 'library' ? '' : 'hidden'}`}>
        <p className="text-xs text-gray-500 dark:text-gray-400 text-center">
          Click any section to add it to your page
        </p>
      </div>

      {/* Preview Modal */}
      {previewSection && (() => {
        const previewData = getSectionPreviewData(previewSection.type);
        const templateData = SECTION_TEMPLATES.find((t) => t.type === previewSection.type)?.defaultData;
        const fallbackData = templateData || {
          id: 'preview-fallback',
          type: previewSection.type as any,
          order: 0,
          data: {},
          style: {},
        };
        
        return (
          <SectionPreviewModal
            isOpen={true}
            sectionType={previewSection.type}
            sectionName={previewSection.name}
            sectionDescription={previewSection.description}
            sampleData={previewData || fallbackData}
            onClose={() => setPreviewSection(null)}
            onAddSection={() => {
              onAddSection(previewSection.type);
              setPreviewSection(null);
            }}
          />
        );
      })()}
    </div>
  );
}